import type { Translator } from "@/i18n/translate";

const LLM_PROVIDER_LABELS: Record<string, string> = { anthropic: "Anthropic Claude", openai: "OpenAI", nvidia: "NVIDIA NIM" };

/** Who generated an AI draft, for "Generated by …" lines. */
export function aiProviderLabel(provider: string | null, t: Translator): string | null {
  if (!provider) return null;
  if (provider === "demo") return t("ai.provider.demo");
  if (provider === "demo-seed") return t("ai.provider.seed");
  return LLM_PROVIDER_LABELS[provider] ?? provider;
}
